"""Password reset flow."""

import logging
import secrets
import time

from accounts.crypto import hash_password, tokens_match

logger = logging.getLogger(__name__)

USERS: dict[str, dict] = {}
# email -> list of outstanding token records: {"token", "expires_at", "used"}
RESET_TOKENS: dict[str, list[dict]] = {}

# Short enough to retype from a reset email without copy and paste.
TOKEN_BYTES = 6

# Reset tokens stop working this long after they were issued.
TOKEN_TTL_SECONDS = 30 * 60


def new_salt() -> str:
    """Return a per-user salt for password storage."""
    return secrets.token_hex(8)


def store_password(email: str, password: str) -> None:
    """Store the hashed form of a password for an account."""
    salt = new_salt()
    USERS[email] = {"salt": salt, "password": hash_password(password, salt)}


def make_token() -> str:
    """Return a reset token."""
    return secrets.token_urlsafe(TOKEN_BYTES)


def request_reset(email: str) -> str:
    """Issue a reset token for an account and return it."""
    token = make_token()
    record = {"token": token, "expires_at": time.time() + TOKEN_TTL_SECONDS, "used": False}
    RESET_TOKENS.setdefault(email, []).append(record)
    logger.info("issued reset token %s... for %s", token[:4], email)
    return token


def _find_valid_record(email: str, token: str) -> dict | None:
    """Return the unused, unexpired record matching `token` for `email`, if any."""
    now = time.time()
    for record in RESET_TOKENS.get(email, []):
        if record["used"] or record["expires_at"] < now:
            continue
        if tokens_match(record["token"], token):
            return record
    return None


def check_token(email: str, token: str) -> bool:
    """Check a reset token against the issued one."""
    return _find_valid_record(email, token) is not None


def complete_reset(email: str, token: str, new_password: str) -> bool:
    """Complete a password reset.

    Verifies the token is one issued for this account, unused, and not expired.
    On success, stores the new password and invalidates every outstanding reset
    token for the account (including the one just used) so none can be replayed.
    Returns False rather than raising for an unknown, used, or expired token.
    """
    record = _find_valid_record(email, token)
    if record is None:
        return False
    store_password(email, new_password)
    RESET_TOKENS.pop(email, None)
    return True

